public class IterableMappingMethod extends ContainerMappingMethod {

    public static class Builder extends ContainerMappingMethodBuilder<Builder, IterableMappingMethod> {

        public Builder() {
            super( Builder.class, "collection element" );
        }

        @Override
        protected Type getElementType(Type parameterType) {
            if ( parameterType.isArrayType() ) {
                return parameterType.getComponentType();
            }
            else if ( parameterType.isMapType() ) {
                return ctx.getTypeFactory().getMapEntryType( parameterType );
            }
            return first( parameterType.determineTypeArguments( Iterable.class ) ).getTypeBound();
        }

        @Override
        protected Assignment getWrapper(Assignment assignment, Method method) {
            Type resultType = method.getResultType();
            // target accessor is setter, so decorate assignment as setter
            if ( resultType.isArrayType() || resultType.isMapType() ) {
                Type targetType = resultType.isArrayType() ?
                    resultType.getComponentType() : getElementType( resultType );
                if ( resultType.isMapType() && assignment instanceof MethodReference ) {
                    Type returnType = ( (MethodReference) assignment ).getReturnType();
                    if ( returnType != null ) {
                        targetType = returnType;
                    }
                }
                return new LocalVarWrapper( assignment, method.getThrownTypes(), targetType, false );
            }
            else {
                return new SetterWrapper( assignment, method.getThrownTypes(), false );
            }
        }

        @Override
        protected IterableMappingMethod instantiateMappingMethod(Method method, Collection<String> existingVariables,
